// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint[] memory v) public {
        // Ensure non-empty array to satisfy require
        vm.assume(_tos.length > 0);
        // Ensure arrays have same length
        vm.assume(_tos.length == v.length);
        // Deploy a callee that always succeeds (returns true)
        SuccessCallee callee = new SuccessCallee();
        // Perform the call
        bool result = c.transfer(from, address(callee), _tos, v);
        // Assert that the return value is exactly true (reference returns true, mutant returns false)
        assertTrue(result);
    }
}

contract SuccessCallee {
    fallback() external payable { }
}
